CREATE DATABASE IF NOT EXISTS flowers CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE flowers;
SET FOREIGN_KEY_CHECKS=0;
DROP VIEW IF EXISTS v_order_summary,v_popular_products,v_customer_orders,v_product_ratings,v_daily_sales;
DROP TABLE IF EXISTS order_items,reviews,orders,products,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash CHAR(64) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,category VARCHAR(80) NOT NULL,description TEXT NOT NULL,price DECIMAL(10,2) NOT NULL CHECK(price>=0),image_url VARCHAR(255) NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,total DECIMAL(10,2) NOT NULL CHECK(total>=0),status VARCHAR(30) NOT NULL DEFAULT 'new',delivery_address VARCHAR(255) NOT NULL,delivery_date DATE NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_orders_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE order_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id INT UNSIGNED NOT NULL,product_id INT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL CHECK(quantity>0),price DECIMAL(10,2) NOT NULL CHECK(price>=0),CONSTRAINT fk_items_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,CONSTRAINT fk_items_product FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE reviews (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,product_id INT UNSIGNED NULL,rating TINYINT UNSIGNED NOT NULL CHECK(rating BETWEEN 1 AND 5),text TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_reviews_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_reviews_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
