INSERT INTO products(name,category,description,price,image_url) VALUES ('Пионовый вечер','Букеты','Пионы, розы и эвкалипт в спокойной палитре.',4590,'/static/images/bouquet1.jpg'),('Нежное утро','Букеты','Розовые розы и кремовая гортензия.',3290,'/static/images/bouquet2.jpg'),('Садовая история','Композиции','Свежая композиция с сезонной зеленью.',5190,'/static/images/bouquet3.jpg'),('Белая классика','Розы','Лаконичный букет из белых роз.',3890,'/static/images/bouquet4.jpg'),('Тёплое письмо','Подарки','Букет с открыткой для важного человека.',2790,'/static/images/bouquet5.jpg'),('Ваза с ранункулюсами','Композиции','Небольшая интерьерная композиция.',3490,'/static/images/bouquet6.jpg');
CREATE VIEW v_order_summary AS SELECT o.id,u.name AS customer,u.email,o.total,o.status,o.delivery_date FROM orders o JOIN users u ON u.id=o.user_id;
CREATE VIEW v_popular_products AS SELECT p.id,p.name,COALESCE(SUM(oi.quantity),0) AS sold FROM products p LEFT JOIN order_items oi ON oi.product_id=p.id GROUP BY p.id,p.name ORDER BY sold DESC;
CREATE VIEW v_customer_orders AS SELECT u.id AS user_id,u.name,COUNT(o.id) AS orders_count,COALESCE(SUM(o.total),0) AS spent FROM users u LEFT JOIN orders o ON o.user_id=u.id GROUP BY u.id,u.name;
CREATE VIEW v_product_ratings AS SELECT p.id,p.name,ROUND(AVG(r.rating),1) AS rating,COUNT(r.id) AS reviews_count FROM products p LEFT JOIN reviews r ON r.product_id=p.id GROUP BY p.id,p.name;
CREATE VIEW v_daily_sales AS SELECT DATE(created_at) AS sale_date,COUNT(*) AS orders_count,SUM(total) AS revenue FROM orders GROUP BY DATE(created_at) ORDER BY sale_date DESC;
